brp AS (
  SELECT f, page_id, end_time,
    SUM(IF(breakdown_dimension = 'is_from_ads' AND breakdown_value = '1', media_view, NULL))       AS mv_anuncio,
    SUM(IF(breakdown_dimension = 'is_from_ads' AND breakdown_value = '0', media_view, NULL))       AS mv_organica,
    SUM(IF(breakdown_dimension = 'is_from_followers' AND breakdown_value = '1', media_view, NULL)) AS mv_seguidores,
    SUM(IF(breakdown_dimension = 'is_from_followers' AND breakdown_value = '0', media_view, NULL)) AS mv_nao_seguidores,
    COUNT(*) AS qtd_linhas_breakdown
  FROM br
  GROUP BY 1, 2, 3
)
SELECT
  CONCAT('facebook-pages-', x.f, ':', x.page_id, ':',
         CAST(DATE_SUB(DATE(x.end_time, 'America/Los_Angeles'), INTERVAL 1 DAY) AS STRING))  AS id_insight_diario,
  x.page_id                                                    AS id_pagina,
  x.end_time                                                   AS fim_periodo_utc,
  DATE_SUB(DATE(x.end_time, 'America/Los_Angeles'), INTERVAL 1 DAY)                          AS data_metrica,
  DATE_TRUNC(DATE_SUB(DATE(x.end_time, 'America/Los_Angeles'), INTERVAL 1 DAY), MONTH)       AS mes_referencia,
  x.page_views_total                                           AS visualizacoes_pagina,
  x.page_post_engagements                                      AS engajamentos_posts,
  x.page_posts_impressions_organic                             AS impressoes_posts_organicas,
  x.page_actions_post_reactions_like_total                     AS reacoes_curtir,
  x.page_actions_post_reactions_love_total                     AS reacoes_amei,
  x.page_actions_post_reactions_wow_total                      AS reacoes_uau,
  x.page_actions_post_reactions_haha_total                     AS reacoes_haha,
  x.page_actions_post_reactions_sorry_total                    AS reacoes_triste,
  x.page_actions_post_reactions_anger_total                    AS reacoes_grr,
  x.page_video_views                                           AS video_views,
  x.page_video_views_paid                                      AS video_views_pagas,
  x.page_video_views_organic                                   AS video_views_organicas,
  x.page_video_views_autoplayed                                AS video_views_autoplay,
  x.page_video_views_click_to_play                             AS video_views_clique_para_reproduzir,
  x.page_video_views_unique                                    AS video_views_unicas,
  x.page_video_repeat_views                                    AS video_views_repetidas,
  x.page_video_view_time                                       AS video_tempo_assistido_ms,
  x.page_video_complete_views_30s                              AS video_views_30s,
  x.page_video_complete_views_30s_paid                         AS video_views_30s_pagas,
  x.page_video_complete_views_30s_organic                      AS video_views_30s_organicas,
  x.page_video_complete_views_30s_autoplayed                   AS video_views_30s_autoplay,
  x.page_video_complete_views_30s_click_to_play                AS video_views_30s_clique_para_reproduzir,
  x.page_video_complete_views_30s_unique                       AS video_views_30s_unicas,
  x.page_video_complete_views_30s_repeat_views                 AS video_views_30s_repetidas,
  x.page_media_view                                            AS media_views,
  x.page_total_media_view_unique                               AS media_views_unicas,
  r.mv_anuncio                                                 AS media_views_de_anuncio,
  r.mv_organica                                                AS media_views_organicas,
  r.mv_seguidores                                              AS media_views_de_seguidores,
  r.mv_nao_seguidores                                          AS media_views_de_nao_seguidores,
  (r.f IS NOT NULL)                                            AS flag_breakdown_presente,
  (x.end_time = MAX(x.end_time) OVER (PARTITION BY x.f, x.page_id))                          AS flag_ultimo_periodo_da_fonte,
  CURRENT_TIMESTAMP()                                          AS _extraido_at,
  CONCAT('facebook-pages-', x.f)                               AS _fonte,
  TO_HEX(MD5(TO_JSON_STRING(x)))                               AS _payload_hash
FROM d x
LEFT JOIN brp r ON r.f = x.f AND r.page_id = x.page_id AND r.end_time = x.end_time
